"""Bounded ordinary-user subprocess for PUBLIC sanity checks, not private grading.

The enclosing container/workspace supplies filesystem isolation. The child helper
adds the published rlimits and seccomp policy without root, chroot or UID leases.
"""
from dataclasses import dataclass
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import time


class InfrastructureError(RuntimeError):
    pass


class CandidateFailure(RuntimeError):
    pass


@dataclass
class Result:
    stdout: bytes
    stderr: bytes
    returncode: int
    seconds: float


def storage_over_budget(root):
    total=0
    entries=0
    stack=[Path(root)]
    while stack:
        path=stack.pop()
        try:
            st=path.lstat()
            entries+=1
            if stat.S_ISREG(st.st_mode):
                total+=max(st.st_size,st.st_blocks*512)
            elif stat.S_ISDIR(st.st_mode):
                with os.scandir(path) as it:
                    for entry in it:
                        stack.append(Path(entry.path))
                        if entries+len(stack)>4096:
                            return True
        except FileNotFoundError:
            continue
        if total>64*1024*1024 or entries>4096:
            return True
    return False


def invoke(worker,argv,data,scratch,*,timeout=180,stdout_limit=8*1024*1024,stderr_limit=256*1024,pythonpath=None):
    """Run a single non-forking child with bounded real stdin/stdout/stderr pipes."""
    if os.getuid()==0 or os.geteuid()==0:
        raise InfrastructureError('public check must run as an ordinary nonroot user')
    if not isinstance(data,bytes) or len(data)>8*1024*1024:
        raise InfrastructureError('public fixture input exceeds byte bound')
    if not 0<timeout<=180 or stdout_limit<0 or stderr_limit<0:
        raise InfrastructureError('invalid public capture budget')
    worker=Path(worker).resolve()
    if not worker.is_file() or not os.access(worker,os.X_OK) or worker.stat().st_mode&0o6000:
        raise InfrastructureError('missing or unsafe public check_worker executable')
    scratch=Path(scratch).resolve()
    scratch.mkdir(mode=0o700)
    env={'PATH':'/usr/local/bin:/usr/bin:/bin','HOME':str(scratch.parent),
         'LANG':'C','LC_ALL':'C','TMPDIR':str(scratch),
         'PYTHONUNBUFFERED':'1','PYTHONDONTWRITEBYTECODE':'1','PYTHONHASHSEED':'0',
         'OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'}
    if pythonpath is not None:
        env['PYTHONPATH']=str(pythonpath)
        env['LD_LIBRARY_PATH']=str(Path(pythonpath).parent/'native')
    start=time.monotonic()
    deadline=start+timeout
    next_storage=start
    process=None
    streams=[]
    selector=selectors.DefaultSelector()
    output=[bytearray(),bytearray()]
    offset=0
    try:
        # Protect the launch/handle assignment against an interruption. The C
        # helper restores the child's signal mask before applying its policy.
        old_mask=signal.pthread_sigmask(signal.SIG_BLOCK,{signal.SIGTERM,signal.SIGINT})
        try:
            process=subprocess.Popen([str(worker),*argv],stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                                     cwd=scratch.parent,env=env,close_fds=True)
            streams=[process.stdin,process.stdout,process.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK,old_mask)
        for stream in streams:
            os.set_blocking(stream.fileno(),False)
        if data:
            selector.register(process.stdin,selectors.EVENT_WRITE,-1)
        else:
            process.stdin.close()
        selector.register(process.stdout,selectors.EVENT_READ,0)
        selector.register(process.stderr,selectors.EVENT_READ,1)
        while selector.get_map() or process.poll() is None:
            now=time.monotonic()
            if now>=deadline:
                raise CandidateFailure('candidate wall deadline exceeded')
            if now>=next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('sampled writable storage emergency budget exceeded')
                next_storage=now+.25
            for key,_ in selector.select(min(.1,deadline-now)):
                stream,index=key.fileobj,key.data
                if index==-1:
                    try:
                        sent=os.write(stream.fileno(),memoryview(data)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        selector.unregister(stream);stream.close();continue
                    offset+=sent
                    if offset==len(data):
                        selector.unregister(stream);stream.close()
                else:
                    limit=(stdout_limit,stderr_limit)[index]
                    try:
                        block=os.read(stream.fileno(),min(65536,limit-len(output[index])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        selector.unregister(stream);stream.close()
                    elif len(output[index])+len(block)>limit:
                        raise CandidateFailure(('stdout','stderr')[index]+' byte limit exceeded')
                    else:
                        output[index].extend(block)
        # Streams may close before the child exits; EOF alone is not success.
        try:
            code=process.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired as exc:
            raise CandidateFailure('candidate wall deadline exceeded') from exc
        if storage_over_budget(scratch):
            raise InfrastructureError('sampled writable storage emergency budget exceeded')
        return Result(bytes(output[0]),bytes(output[1]),code,time.monotonic()-start)
    finally:
        try:
            if process is not None:
                if process.poll() is None:
                    process.kill()
                process.wait(timeout=5)
        except BaseException as exc:
            raise InfrastructureError('public child cleanup failed') from exc
        finally:
            selector.close()
            for stream in streams:
                stream.close()

