"""Certified CPU numerics for the offline sharing replay.

Two solvers live here:

* ``solve_worker_problem``: the strictly convex path-based worker QP with its
  tangent lower-bound certificate (amounts in traffic units).
* ``controller_solve``: the one-domain controller projection with its pressure
  complementarity certificate (utilization units).

Both are exact active-set / breakpoint solves in float64; no external solver,
no iteration heuristics are needed at these dimensions.
"""
from __future__ import annotations

import numpy as np


# --------------------------------------------------------------------------
# worker problem
# --------------------------------------------------------------------------

def _face_solve(H, b, dv, slot_com, idx, tidx, n, m):
    """Equality-constrained minimizer on the face x_Z = 0, (P^T x)_T = d_T."""
    x = np.zeros(n)
    lam = np.zeros(m)
    ni = len(idx)
    nt = len(tidx)
    if ni == 0:
        return x, lam
    KKT = np.zeros((ni + nt, ni + nt))
    KKT[:ni, :ni] = H[np.ix_(idx, idx)]
    if nt:
        pos = {k: j for j, k in enumerate(tidx)}
        Pm = np.zeros((ni, nt))
        for i, s in enumerate(idx):
            j = pos.get(slot_com[s])
            if j is not None:
                Pm[i, j] = 1.0
        KKT[:ni, ni:] = Pm
        KKT[ni:, :ni] = Pm.T
    rhs = np.zeros(ni + nt)
    rhs[:ni] = -b[idx]
    for j, k in enumerate(tidx):
        rhs[ni + j] = dv[k]
    sol = np.linalg.solve(KKT, rhs)
    x[idx] = sol[:ni]
    for j, k in enumerate(tidx):
        lam[k] = sol[ni + j]
    return x, lam


def _active_set_solve(H, b, dv, slot_com, m, mode):
    """Feasible primal active-set for min 0.5 x'Hx + b'x with x >= 0 and
    P^T x = d (route) or P^T x <= d (admit) on each commodity block.

    Returns (x, lam) with lam the sum-constraint potentials.
    """
    n = H.shape[0]
    cnt = np.zeros(m, dtype=np.int64)
    for s in range(n):
        cnt[slot_com[s]] += 1
    Z = np.zeros(n, dtype=bool)          # slots fixed at the zero bound
    T = np.zeros(m, dtype=bool)          # commodities with active sum
    x = np.zeros(n)
    if mode == 'route':
        T[:] = True
        for s in range(n):
            x[s] = dv[slot_com[s]] / cnt[slot_com[s]]
    else:
        Z[:] = True
    lam = np.zeros(m)
    limit = 2000 + 20 * n
    for _ in range(limit):
        idx = [s for s in range(n) if not Z[s]]
        tidx = [k for k in range(m) if T[k]]
        x_new, lam_new = _face_solve(H, b, dv, slot_com, idx, tidx, n, m)
        p = x_new - x
        if not p.any():
            g = H @ x_new + b
            for s in range(n):
                g[s] += lam_new[slot_com[s]]
            drop = None
            for s in range(n):
                if Z[s] and g[s] < 0:
                    drop = ('s', s)
                    break
            if drop is None and mode == 'admit':
                for k in range(m):
                    if T[k] and lam_new[k] < 0:
                        drop = ('k', k)
                        break
            if drop is None:
                return x_new, lam_new
            if drop[0] == 's':
                Z[drop[1]] = False
            else:
                T[drop[1]] = False
            x = x_new
            lam = lam_new
            continue
        # step toward the face minimizer, blocking at the boundary
        cands = []
        for s in range(n):
            if not Z[s] and p[s] < 0:
                a_s = (-x[s] / p[s]) if x[s] > 0 else 0.0
                cands.append((a_s, ('s', s)))
        if mode == 'admit':
            Xk = np.zeros(m)
            for s in range(n):
                Xk[slot_com[s]] += x[s]
            slope = np.zeros(m)
            for s in range(n):
                slope[slot_com[s]] += p[s]
            for k in range(m):
                if not T[k] and slope[k] > 0:
                    a_k = (dv[k] - Xk[k]) / slope[k]
                    if a_k >= 0:
                        cands.append((a_k, ('k', k)))
        alpha = 1.0
        for a, _tgt in cands:
            if a < alpha:
                alpha = a
        if alpha == 1.0:
            x = x_new.copy()
        else:
            x = x + alpha * p
        for a, tgt in cands:
            if a == alpha:
                if tgt[0] == 's':
                    Z[tgt[1]] = True
                    x[tgt[1]] = 0.0
                else:
                    T[tgt[1]] = True
    raise RuntimeError('active-set iteration limit')


def solve_worker_problem(E, c, B, rho, mode, owned, demands, slots):
    """Build and solve the captured worker problem.

    Parameters
    ----------
    E : int            number of edges
    c : list[int]      captured capacities (length E)
    B : array (E,)     captured normalized signed bias
    rho : int          captured penalty
    mode : str         'route' or 'admit' (captured)
    owned : list[int]  owned global commodity ids in worker-list order
    demands : list     captured demands indexed by global commodity id
    slots : list       captured paths indexed by global commodity id

    Returns the proposal dict (optimal / infeasible).
    """
    Bv = np.asarray(B, dtype=np.float64)
    avail = {}
    for k in owned:
        row = []
        for path in slots[k]:
            if path is None:
                row.append(False)
            else:
                ok = True
                for e in path:
                    if c[e] <= 0:
                        ok = False
                        break
                row.append(ok)
        avail[k] = row
    unroutable = [k for k in owned if not any(avail[k])]
    if mode == 'route':
        for k in unroutable:
            if demands[k] > 0:
                return {'status': 'infeasible', 'unroutable': sorted(unroutable)}
    var = []
    for k in owned:
        if demands[k] > 0:
            for p, path in enumerate(slots[k]):
                if avail[k][p]:
                    var.append((k, p, path))
    pos = {k: i for i, k in enumerate(owned)}
    flow = [[0.0] * len(slots[k]) for k in owned]
    pot = [0.0] * len(owned)
    if not var:
        return {'status': 'optimal', 'flow': flow,
                'edge_load': [0.0] * E, 'potential': pot}
    n = len(var)
    kvars = []
    for k, _p, _path in var:
        if k not in kvars:
            kvars.append(k)
    m = len(kvars)
    kidx = {k: j for j, k in enumerate(kvars)}
    dv = np.array([demands[k] for k in kvars], dtype=np.float64)
    slot_com = np.array([kidx[k] for (k, _p, _path) in var], dtype=np.int64)
    col = np.zeros((n, E))
    for s, (_k, _p, path) in enumerate(var):
        for e in path:
            col[s, e] = 1.0 / c[e]
    H = np.eye(n) + rho * (col @ col.T)
    b = -rho * (col @ Bv)
    if mode == 'admit':
        b = b - 1.0
    x, lam = _active_set_solve(H, b, dv, slot_com, m, mode)
    for s, (k, p, _path) in enumerate(var):
        v = x[s]
        if -1e-12 < v < 0.0:
            v = 0.0
        flow[pos[k]][p] = float(v)
    load = np.zeros(E)
    for s, (_k, _p, path) in enumerate(var):
        v = x[s]
        if -1e-12 < v < 0.0:
            v = 0.0
        for e in path:
            load[e] += v
    for j, k in enumerate(kvars):
        pot[pos[k]] = float(lam[j])
    return {'status': 'optimal', 'flow': flow,
            'edge_load': [float(v) for v in load],
            'potential': pot}


# --------------------------------------------------------------------------
# controller projection
# --------------------------------------------------------------------------

def controller_solve(V, rho, mode):
    """Solve the one-domain controller problem on live edges.

    route: min h + 0.5*rho*sum (z-V)^2,  h >= 0, z <= h.
    admit: min     0.5*rho*sum (z-V)^2,  h = 1,  z <= 1.

    Returns (h, z, t) with t the pressure certificate.
    """
    V = np.asarray(V, dtype=np.float64)
    n = V.shape[0]
    if mode == 'route':
        if n == 0:
            h = 0.0
        else:
            g0 = float(rho * np.sum(np.maximum(V, 0.0)))
            if g0 <= 1.0:
                h = 0.0
            else:
                w = np.sort(V)[::-1]
                total = 0.0
                h = 0.0
                for mm in range(1, n + 1):
                    total += w[mm - 1]
                    hm = (rho * total - 1.0) / (rho * mm)
                    if mm == n or hm >= w[mm]:
                        h = hm
                        break
        z = np.minimum(V, h)
    else:
        h = 1.0
        z = np.minimum(V, 1.0) if n else np.zeros(0)
    t = rho * (V - z)
    return float(h), z, t
