"""Cross-validate engine solvers against brute-force methods."""
import itertools
import sys
import random
import numpy as np
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/.deps')
from te.engine import solve_worker_problem, controller_solve


def brute_worker(H, b, dv, slot_com, m, mode):
    """Enumerate supports; pick KKT-consistent optimum."""
    n = H.shape[0]
    best = None
    # candidate supports over slots; commodities forced equal (route) / free (admit)
    for r in range(n + 1):
        for S in itertools.combinations(range(n), r):
            Zset = set(range(n)) - set(S)
            # route: all commodities in T; admit: enumerate T subsets
            Tk = range(m) if mode == 'route' else [None]
            for T in Tk:
                if T is None:
                    tsubsets = [frozenset(t) for r2 in range(m + 1)
                                for t in itertools.combinations(range(m), r2)]
                else:
                    tsubsets = [frozenset(range(m))]
                for Ts in tsubsets:
                    # every k in Ts needs a free slot
                    ok = all(any(slot_com[s] == k for s in S) for k in Ts)
                    if not ok:
                        continue
                    if mode == 'route' and r == 0:
                        continue
                    idx = list(S)
                    tidx = sorted(Ts)
                    ni, nt = len(idx), len(tidx)
                    if ni == 0 and nt == 0 and mode == 'route' and m:
                        continue
                    try:
                        if ni + nt == 0:
                            x = np.zeros(n); lam = np.zeros(m)
                        else:
                            KKT = np.zeros((ni + nt, ni + nt))
                            if ni:
                                KKT[:ni, :ni] = H[np.ix_(idx, idx)]
                            if nt:
                                Pm = np.zeros((ni, nt))
                                pos = {k: j for j, k in enumerate(tidx)}
                                for i, s in enumerate(idx):
                                    if slot_com[s] in pos:
                                        Pm[i, pos[slot_com[s]]] = 1.0
                                if ni:
                                    KKT[:ni, ni:] = Pm
                                    KKT[ni:, :ni] = Pm.T
                            rhs = np.zeros(ni + nt)
                            if ni:
                                rhs[:ni] = -b[idx]
                            for j, k in enumerate(tidx):
                                rhs[ni + j] = dv[k]
                            sol = np.linalg.solve(KKT, rhs)
                            x = np.zeros(n); lam = np.zeros(m)
                            if ni:
                                x[idx] = sol[:ni]
                            for j, k in enumerate(tidx):
                                lam[k] = sol[ni + j]
                    except np.linalg.LinAlgError:
                        continue
                    if np.any(x < -1e-9):
                        continue
                    g = H @ x + b + lam[slot_com]
                    if np.any(g[Zset] < -1e-9):
                        continue
                    if mode == 'admit' and np.any(lam[list(Ts)] < -1e-9):
                        continue
                    Xk = np.zeros(m)
                    for s in range(n):
                        Xk[slot_com[s]] += x[s]
                    if np.any(Xk > dv + 1e-9):
                        continue
                    if mode == 'route' and np.any(np.abs(Xk - dv) > 1e-9):
                        continue
                    if mode == 'admit':
                        for k in range(m):
                            if k not in Ts and lam[k] != 0:
                                lam[k] = 0.0
                    f = 0.5 * x @ H @ x + b @ x
                    if best is None or f < best[0] - 1e-12:
                        best = (f, x.copy(), lam.copy())
    return best


def brute_controller(V, rho, mode):
    if mode == 'admit':
        h = 1.0
        z = np.minimum(V, 1.0)
    else:
        lo, hi = 0.0, max(0.0, float(np.max(V)) if len(V) else 0.0) + 2.0
        def g(hv):
            return rho * float(np.sum(np.maximum(V - hv, 0.0)))
        if g(0.0) <= 1.0:
            h = 0.0
        else:
            for _ in range(200):
                mid = (lo + hi) / 2
                if g(mid) > 1.0:
                    lo = mid
                else:
                    hi = mid
            h = (lo + hi) / 2
        z = np.minimum(V, h)
    t = rho * (V - z)
    return h, z, t


def run(trials=300, seed=0):
    rng = random.Random(seed)
    bad = 0
    for it in range(trials):
        n = rng.randint(1, 6)
        m = rng.randint(1, 3)
        slot_com = np.array([rng.randrange(m) for _ in range(n)], dtype=np.int64)
        for k in range(m):
            if not np.any(slot_com == k):
                slot_com[rng.randrange(n)] = k
        # build a random topology-derived H to mimic real problems
        E = rng.randint(1, 5)
        col = np.zeros((n, E))
        for s in range(n):
            for e in range(E):
                if rng.random() < 0.4:
                    col[s, e] = 1.0 / rng.randint(1, 4)
        rho = rng.randint(1, 8)
        H = np.eye(n) + rho * (col @ col.T)
        B = np.array([rng.uniform(-3, 3) for _ in range(E)])
        b = -rho * (col @ B)
        mode = rng.choice(['route', 'admit'])
        if mode == 'admit':
            b = b - 1.0
        dv = np.array([rng.randint(1, 5) for _ in range(m)], dtype=np.float64)
        xs, lams = solve_with_arrays(H, b, dv, slot_com, m, mode)
        bf = brute_worker(H, b, dv, slot_com, m, mode)
        if bf is None:
            print('brute found nothing (route with degenerate?)', it)
            continue
        if np.max(np.abs(xs - bf[1])) > 1e-7 or np.max(np.abs(lams - bf[2])) > 1e-6:
            bad += 1
            print('WORKER MISMATCH trial', it, 'mode', mode)
            print(' active x', xs, lams)
            print(' brute  x', bf[1], bf[2])
            if bad > 3:
                return 1
        # controller
        V = np.array([rng.uniform(-2, 3) for _ in range(rng.randint(0, 6))])
        h1, z1, t1 = controller_solve(V, rho, mode)
        h2, z2, t2 = brute_controller(V, rho, mode)
        if abs(h1 - h2) > 1e-7 or np.max(np.abs(z1 - z2)) > 1e-7:
            bad += 1
            print('CTRL MISMATCH', it, h1, h2, V)
    print('cross done bad=%d' % bad)
    return 1 if bad else 0


def solve_with_arrays(H, b, dv, slot_com, m, mode):
    from te.engine import _active_set_solve
    return _active_set_solve(H, b, dv, slot_com, m, mode)


if __name__ == '__main__':
    sys.exit(run(200, int(sys.argv[1]) if len(sys.argv) > 1 else 0))
